/// <summary>
/// HSMobileOpsCountControlSvc's answer: Success, or ErrorCode and Message; PayloadJson holds what
/// the operation returns (see each operation).
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountCtlResponse
{
    boolean success;
    str errorCode;
    str message;
    str payloadJson;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('PayloadJson')]
public str parmPayloadJson(str _value = payloadJson)
{
    payloadJson = _value;
    return payloadJson;
}
